# Find a zebra crossing with parked cars on the right side
zebra_crossings = MAP.crossings(control="zebra")
if not zebra_crossings:
    raise Exception("No zebra crossings found on the map")

# Try each crossing until we find one with enough kerb slots
found = False
for cr in zebra_crossings:
    cid = cr["id"]
    road = cr["road"]
    centre = MAP.place(cid)

    # Get kerb slots for parked cars
    slots = MAP.kerb_slots(road, "right", spacing=7.0)

    # Filter for slots far enough from center and take up to 4
    slots = sorted([p for p in slots if p.dist(centre) > 8.0], key=lambda p: p.dist(centre))[:4]

    if len(slots) >= 4:
        # Found a suitable crossing
        break
    else:
        continue

if not found:
    raise Exception(f"Not enough kerb slots for 4 cars at any zebra crossing")

